<?php
use App\Models\{AdditionalChargeType,CommercialConfigurationEvent,CompanyPaymentMethod};
use function Livewire\Volt\{computed,layout,state};
layout('layouts.app');
state(['payment_id'=>null,'payment_type'=>'bank','display_name'=>'','provider'=>'','bank_name'=>'','account_name'=>'','account_number'=>'','phone_or_business_number'=>'','branch_name'=>'','currency'=>'TZS','instructions'=>'','payment_active'=>true,'sort_order'=>0,'show_on_quotation'=>true,'show_on_proforma'=>true,'show_on_invoice'=>true,'charge_type_id'=>null,'charge_name'=>'','charge_description'=>'','charge_active'=>true,'charge_sort_order'=>0]);
$paymentMethods=computed(fn()=>CompanyPaymentMethod::withoutGlobalScopes()->where('company_id',auth()->user()->company_id)->orderBy('sort_order')->orderBy('id')->get());
$chargeTypes=computed(fn()=>AdditionalChargeType::withoutGlobalScopes()->where('company_id',auth()->user()->company_id)->orderBy('sort_order')->orderBy('id')->get());
$audit=function($subject,string $event,array $metadata=[]){CommercialConfigurationEvent::withoutGlobalScopes()->create(['company_id'=>auth()->user()->company_id,'user_id'=>auth()->id(),'subject_type'=>$subject instanceof CompanyPaymentMethod?'payment_method':'charge_type','subject_id'=>$subject->id,'event'=>$event,'metadata'=>$metadata]);};
$resetPayment=function(){$this->payment_id=null;$this->payment_type='bank';$this->display_name=$this->provider=$this->bank_name=$this->account_name=$this->account_number=$this->phone_or_business_number=$this->branch_name=$this->instructions='';$this->currency='TZS';$this->payment_active=$this->show_on_quotation=$this->show_on_proforma=$this->show_on_invoice=true;$this->sort_order=0;};
$editPayment=function(int $id){$m=CompanyPaymentMethod::withoutGlobalScopes()->where('company_id',auth()->user()->company_id)->findOrFail($id);foreach(['type'=>'payment_type','display_name'=>'display_name','provider'=>'provider','bank_name'=>'bank_name','account_name'=>'account_name','account_number'=>'account_number','phone_or_business_number'=>'phone_or_business_number','branch_name'=>'branch_name','currency'=>'currency','instructions'=>'instructions','is_active'=>'payment_active','sort_order'=>'sort_order','show_on_quotation'=>'show_on_quotation','show_on_proforma'=>'show_on_proforma','show_on_invoice'=>'show_on_invoice'] as $field=>$state)$this->{$state}=$m->{$field}??'';$this->payment_id=$m->id;};
$savePayment=function(){abort_unless(auth()->user()->can('payment_methods.manage'),403);$data=$this->validate(['payment_type'=>'required|in:bank,mobile_money,cash,other','display_name'=>'required|string|max:255','provider'=>'nullable|string|max:255','bank_name'=>'nullable|string|max:255','account_name'=>'nullable|string|max:255','account_number'=>'nullable|string|max:255','phone_or_business_number'=>'nullable|string|max:255','branch_name'=>'nullable|string|max:255','currency'=>'required|string|max:10','instructions'=>'nullable|string|max:1000','payment_active'=>'boolean','sort_order'=>'integer|min:0','show_on_quotation'=>'boolean','show_on_proforma'=>'boolean','show_on_invoice'=>'boolean']);$values=['company_id'=>auth()->user()->company_id,'type'=>$data['payment_type'],'display_name'=>$data['display_name'],'provider'=>$data['provider']?:null,'bank_name'=>$data['bank_name']?:null,'account_name'=>$data['account_name']?:null,'account_number'=>$data['account_number']?:null,'phone_or_business_number'=>$data['phone_or_business_number']?:null,'branch_name'=>$data['branch_name']?:null,'currency'=>strtoupper($data['currency']),'instructions'=>$data['instructions']?:null,'is_active'=>$data['payment_active'],'sort_order'=>$data['sort_order'],'show_on_quotation'=>$data['show_on_quotation'],'show_on_proforma'=>$data['show_on_proforma'],'show_on_invoice'=>$data['show_on_invoice']];$m=$this->payment_id?CompanyPaymentMethod::withoutGlobalScopes()->where('company_id',auth()->user()->company_id)->findOrFail($this->payment_id):new CompanyPaymentMethod;$created=!$m->exists;$m->fill($values)->save();$this->audit($m,$created?'created':'edited',['type'=>$m->type,'display_name'=>$m->display_name,'is_active'=>$m->is_active]);$this->resetPayment();session()->flash('success','Payment method saved.');};
$togglePayment=function(int $id){abort_unless(auth()->user()->can('payment_methods.manage'),403);$m=CompanyPaymentMethod::withoutGlobalScopes()->where('company_id',auth()->user()->company_id)->findOrFail($id);$m->update(['is_active'=>!$m->is_active]);$this->audit($m,$m->is_active?'activated':'deactivated',['display_name'=>$m->display_name]);};
$resetCharge=function(){$this->charge_type_id=null;$this->charge_name=$this->charge_description='';$this->charge_active=true;$this->charge_sort_order=0;};
$editCharge=function(int $id){$c=AdditionalChargeType::withoutGlobalScopes()->where('company_id',auth()->user()->company_id)->findOrFail($id);$this->charge_type_id=$c->id;$this->charge_name=$c->name;$this->charge_description=$c->description?:'';$this->charge_active=$c->is_active;$this->charge_sort_order=$c->sort_order;};
$saveCharge=function(){abort_unless(auth()->user()->can('additional_charge_types.manage'),403);$data=$this->validate(['charge_name'=>'required|string|max:255','charge_description'=>'nullable|string|max:1000','charge_active'=>'boolean','charge_sort_order'=>'integer|min:0']);$c=$this->charge_type_id?AdditionalChargeType::withoutGlobalScopes()->where('company_id',auth()->user()->company_id)->findOrFail($this->charge_type_id):new AdditionalChargeType;$created=!$c->exists;$c->fill(['company_id'=>auth()->user()->company_id,'name'=>$data['charge_name'],'description'=>$data['charge_description']?:null,'is_active'=>$data['charge_active'],'sort_order'=>$data['charge_sort_order']])->save();$this->audit($c,$created?'created':'edited',['name'=>$c->name,'is_active'=>$c->is_active]);$this->resetCharge();session()->flash('success','Additional charge type saved.');};
$toggleCharge=function(int $id){abort_unless(auth()->user()->can('additional_charge_types.manage'),403);$c=AdditionalChargeType::withoutGlobalScopes()->where('company_id',auth()->user()->company_id)->findOrFail($id);$c->update(['is_active'=>!$c->is_active]);$this->audit($c,$c->is_active?'activated':'deactivated',['name'=>$c->name]);};
?>
<div><x-page-header title="Commercial Document Settings" description="Configure display-only payment instructions and reusable additional charge types." :breadcrumbs="['Settings'=>route('settings.index'),'Commercial Documents'=>null]"/><div class="grid gap-6 xl:grid-cols-2"><div class="space-y-6"><x-card title="Payment Methods / Instructions"><p class="mb-4 text-sm text-slate-500">These instructions tell customers how they may pay. They never record a payment or change a balance.</p><div class="grid gap-3 sm:grid-cols-2"><label class="text-sm font-bold">Type<select wire:model="payment_type" class="mt-1 w-full rounded-xl border-slate-200 dark:bg-navy-950">@foreach(CompanyPaymentMethod::TYPES as $t)<option value="{{ $t }}">{{ str($t)->headline() }}</option>@endforeach</select></label><x-form-input label="Display Name" name="display_name" wire:model="display_name"/><x-form-input label="Provider" name="provider" wire:model="provider"/><x-form-input label="Bank Name" name="bank_name" wire:model="bank_name"/><x-form-input label="Account Name" name="account_name" wire:model="account_name"/><x-form-input label="Account Number" name="account_number" wire:model="account_number"/><x-form-input label="Phone / Business Number" name="phone_or_business_number" wire:model="phone_or_business_number"/><x-form-input label="Branch" name="branch_name" wire:model="branch_name"/><x-form-input label="Currency" name="currency" wire:model="currency"/><x-form-input label="Sort Order" name="sort_order" type="number" wire:model="sort_order"/></div><label class="mt-3 block text-sm font-bold">Instructions<textarea wire:model="instructions" class="mt-1 w-full rounded-xl border-slate-200 dark:bg-navy-950"></textarea></label><div class="mt-3 flex flex-wrap gap-4 text-sm font-bold"><label><input type="checkbox" wire:model="payment_active"> Active</label><label><input type="checkbox" wire:model="show_on_quotation"> Quotation</label><label><input type="checkbox" wire:model="show_on_proforma"> Proforma</label><label><input type="checkbox" wire:model="show_on_invoice"> Invoice</label></div>@can('payment_methods.manage')<div class="mt-4 flex gap-2"><button wire:click="savePayment" class="rounded-xl bg-build-orange px-4 py-2 font-black text-white">Save Payment Method</button>@if($payment_id)<button wire:click="resetPayment" class="rounded-xl border px-4 py-2 font-black">Cancel Edit</button>@endif</div>@endcan</x-card><x-card title="Configured Payment Methods"><div class="space-y-3">@forelse($this->paymentMethods as $m)<div class="rounded-xl border p-3 dark:border-slate-700"><div class="flex justify-between gap-3"><div><p class="font-black">{{ $m->display_name }}</p><p class="text-xs text-slate-500">{{ str($m->type)->headline() }} · {{ $m->is_active?'Active':'Inactive' }} · Show: {{ collect(['Quotation'=>$m->show_on_quotation,'Proforma'=>$m->show_on_proforma,'Invoice'=>$m->show_on_invoice])->filter()->keys()->join(', ')?:'None' }}</p></div>@can('payment_methods.manage')<div class="flex gap-2"><button wire:click="editPayment({{ $m->id }})" class="text-sm font-bold text-build-orange">Edit</button><button wire:click="togglePayment({{ $m->id }})" class="text-sm font-bold">{{ $m->is_active?'Deactivate':'Activate' }}</button></div>@endcan</div></div>@empty<p class="text-sm text-slate-500">No payment methods configured.</p>@endforelse</div></x-card></div><div class="space-y-6"><x-card title="Additional Charge Types"><p class="mb-4 text-sm text-slate-500">Reusable non-inventory charges such as transport, loading, offloading, handling, or installation.</p><div class="grid gap-3 sm:grid-cols-2"><x-form-input label="Charge Name" name="charge_name" wire:model="charge_name"/><x-form-input label="Sort Order" name="charge_sort_order" type="number" wire:model="charge_sort_order"/></div><label class="mt-3 block text-sm font-bold">Description<textarea wire:model="charge_description" class="mt-1 w-full rounded-xl border-slate-200 dark:bg-navy-950"></textarea></label><label class="mt-3 block text-sm font-bold"><input type="checkbox" wire:model="charge_active"> Active</label>@can('additional_charge_types.manage')<div class="mt-4 flex gap-2"><button wire:click="saveCharge" class="rounded-xl bg-build-orange px-4 py-2 font-black text-white">Save Charge Type</button>@if($charge_type_id)<button wire:click="resetCharge" class="rounded-xl border px-4 py-2 font-black">Cancel Edit</button>@endif</div>@endcan</x-card><x-card title="Configured Charge Types"><div class="space-y-3">@forelse($this->chargeTypes as $c)<div class="flex justify-between gap-3 rounded-xl border p-3 dark:border-slate-700"><div><p class="font-black">{{ $c->name }}</p><p class="text-xs text-slate-500">{{ $c->is_active?'Active':'Inactive' }} · {{ $c->description }}</p></div>@can('additional_charge_types.manage')<div class="flex gap-2"><button wire:click="editCharge({{ $c->id }})" class="text-sm font-bold text-build-orange">Edit</button><button wire:click="toggleCharge({{ $c->id }})" class="text-sm font-bold">{{ $c->is_active?'Deactivate':'Activate' }}</button></div>@endcan</div>@empty<p class="text-sm text-slate-500">No charge types configured.</p>@endforelse</div></x-card></div></div></div>
